<script setup>
import {ref,computed,onMounted,watch,nextTick} from 'vue'
import {searchEntries} from './support-model.js'
import {prepareImage} from './question-images.js'
const user=ref(null),loading=ref(true),busy=ref(false),error=ref(''),username=ref(''),password=ref('');
const entries=ref([]),province=ref(''),platform=ref(''),question=ref(''),reply=ref(''),source=ref(null),matches=ref([]),searched=ref(false);
const images=ref([]),imageBusy=ref(false),previewImage=ref(null),imageDescription=ref('');
const provinces=computed(()=>[...new Set(entries.value.map(e=>e.province))].sort());
const platforms=computed(()=>[...new Set(entries.value.map(e=>e.platform))].sort());
async function api(action,body){const r=await fetch('/api/support?action='+action,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok){if(r.status===401)user.value=null;throw new Error(d.error||'服务暂不可用')}return d}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){entries.value=(await api('entries')).filter(e=>e.published);let saved;try{saved=JSON.parse(localStorage.getItem('support-platform')||'null')}catch{}if(saved&&entries.value.some(e=>e.platform===saved.platform)){province.value=saved.province;await nextTick();platform.value=saved.platform}}
onMounted(async()=>{try{user.value=(await api('me')).user;await load()}catch(e){if(e.message!=='请登录')error.value=e.message}finally{loading.value=false}});
watch(province,()=>{platform.value='';reset()});watch([platform,question,images],reset);
watch(platform,()=>{try{if(platform.value)localStorage.setItem('support-platform',JSON.stringify({province:province.value,platform:platform.value}));else localStorage.removeItem('support-platform')}catch{}});
function reset(){imageDescription.value='';reply.value='';source.value=null;matches.value=[];searched.value=false}
function choose(e){source.value=e;reply.value=e.answer}
async function generate(){await run(async()=>{reset();if(imageBusy.value)return;if(!question.value.trim()&&!images.value.length)throw new Error('请输入学员问题或上传图片');const submitted={platform:platform.value,question:question.value,images:images.value.map(image=>({...image}))};const result=await api('answer',submitted);if(platform.value!==submitted.platform||question.value!==submitted.question||JSON.stringify(images.value)!==JSON.stringify(submitted.images)){error.value='刚才提交的问题已记录，请重新生成当前问题的回复';return}searched.value=true;imageDescription.value=result.imageDescription||'';if(result.mode==='ai'){source.value={question:'AI 整理回复',source:result.sources.map(s=>s.question+'（'+(s.source||'人工维护')+'）').join('；')};reply.value=result.answer;error.value='问题已登记，AI 回复请核对后发送';return}if(result.mode==='insufficient'){error.value=result.notice;return}matches.value=searchEntries(entries.value,'',platform.value,result.lookupQuestion||question.value);error.value=result.notice||'问题已自动记录到待处理列表';if(matches.value.length===1)choose(matches.value[0]);else if(matches.value.length>1)error.value+='，请选择适用的答案';})}

async function addImages(files){
  if(busy.value||imageBusy.value)return;
  const selected=Array.from(files||[]);if(!selected.length)return;
  if(images.value.length+selected.length>3){error.value='每次最多上传 3 张图片，请先删除多余图片';return}
  imageBusy.value=true;error.value='';
  try{const prepared=[];for(const file of selected)prepared.push(await prepareImage(file));images.value=[...images.value,...prepared]}catch(e){error.value=e.message}finally{imageBusy.value=false}
}
async function selectImages(event){await addImages(event.target.files);event.target.value=''}
function pasteImages(event){const files=Array.from(event.clipboardData?.items||[]).filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter(Boolean);if(files.length){event.preventDefault();addImages(files)}}
async function copy(){try{await navigator.clipboard.writeText(reply.value);error.value='已复制，可粘贴到微信群'}catch{error.value='请选中回复内容后按 Ctrl+C 复制'}}
</script>
<template>
<div v-if="loading" class="loading">正在连接客服工作台…</div>
<div v-else-if="!user" class="login-page"><section class="login-brand"><div class="brand">知答 <span>✦</span></div><small>培训客服工作台</small><h1>粘贴一个问题，<br>找到一份答案。</h1><p>各省平台资料集中维护，<br>让回复更简单。</p></section><form class="login-form" @submit.prevent="run(async()=>{user=(await api('login',{username,password})).user;password='';await load()})"><small>客服端</small><h2>登录客服工作台</h2><label>账号<input v-model="username" required autocomplete="username" maxlength="100"></label><label>密码<input v-model="password" type="password" required autocomplete="current-password" maxlength="256"></label><button class="primary" :disabled="busy">登录</button><p class="message" v-if="error" role="alert">{{error}}</p><p class="hint">请使用管理员分配的客服账号。</p><a href="/admin/login">管理员入口 →</a></form></div>
<div v-else class="customer"><header><div class="brand">知答 <span>✦</span><small>客服工作台</small></div><div class="row"><span>{{user.username}}</span><a v-if="user.role==='admin'" href="/admin/login">管理后台</a><button class="quiet" :disabled="busy" @click="run(async()=>{await api('logout',{});user=null;entries=[];images=[];question='';reset()})">退出</button></div></header><main><div class="heading"><div><small>每一次回复，都有依据</small><h1>粘贴问题，准备回复。</h1><p>平台可选；选择后可匹配该平台已审核的标准答案。</p></div><button class="quiet" :disabled="busy" @click="run(async()=>{await load();reset();error='知识库已刷新'})">刷新知识库</button></div><div class="message" role="status" v-if="error">{{error}}</div><div v-if="!entries.length" class="notice">知识库尚未发布内容，仍可提交问题，由管理员处理后补充答案。</div><div class="result-grid"><form class="card" @submit.prevent="generate"><h2>01　学员的问题</h2><div class="row"><label>培训平台（选填）<select v-model="platform"><option value="">暂不选择平台</option><option v-for="p in platforms" :key="p">{{p}}</option></select></label></div><label>学员问题（文字或图片）<textarea v-model="question" rows="8" maxlength="2000" placeholder="粘贴学员问题，或在此按 Ctrl+V 粘贴截图" @paste="pasteImages" :disabled="busy||imageBusy"></textarea></label><label class="question-upload">上传问题图片<input type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="busy||imageBusy" @change="selectImages"></label><p class="hint">最多 3 张 JPG / PNG / WebP，每张原图不超过 10 MB，上传前自动压缩。支持只传图片；提交后由 AI 识别，再结合所选平台资料回复。未配置 AI 时转人工。</p><p v-if="imageBusy" role="status">正在处理图片，请稍候…</p><div v-if="images.length" class="ticket-images"><div v-for="(image,index) in images" :key="index" class="image-thumbnail"><button type="button" class="preview-button" @click="previewImage=image" :aria-label="'预览图片：'+image.name"><img :src="image.data" :alt="image.name"></button><span>{{image.name}}</span><button type="button" class="quiet" :disabled="busy||imageBusy" @click="images=images.filter((_,i)=>i!==index)">删除图片 {{index+1}}</button></div></div><p class="hint">启用 AI 时截图将发送至 OpenAI 识别。请先遮挡手机号、身份证号等个人信息。系统会记住上次选择的平台。</p><button class="primary" :disabled="busy||imageBusy">{{busy?'正在生成，请稍候…':'生成回复文案 →'}}</button></form><section class="card reply"><h2>02　回复文案</h2><div v-if="imageDescription" class="recognition"><strong>截图识别结果（请核对）</strong><p>{{imageDescription}}</p></div><template v-if="source"><small>答案依据：{{source.question}} · {{source.source||'人工维护'}}</small><textarea v-model="reply" rows="10" aria-label="回复文案"></textarea><button class="primary" :disabled="!reply.trim()" @click="copy">一键复制回复</button><p class="hint">回复依据平台知识生成，AI 可能出错，发送前请核对适用情况。</p></template><div v-else class="empty"><h3>{{searched?'暂未生成回复':'等待学员问题'}}</h3><p>{{searched?(images.length&&!matches.length?'问题和截图已保存；请查看提示和识别结果，必要时由管理员补充回复。':!platform?'问题已进入待处理列表，等待管理员确认平台并补充回复。':matches.length?'请在下方选择对应的知识条目。':'未找到匹配资料，可改用“密码”“学时”等关键词，本次问题已自动进入待处理列表。'):'在左侧粘贴问题，即可匹配标准答案。'}}</p></div></section></div><div v-if="matches.length>1"><h3>请选择适用的答案</h3><button class="result-card" v-for="e in matches" :key="e.id" @click="choose(e)"><h3>{{e.question}}</h3><p>{{e.answer.slice(0,120)}}</p></button></div><footer>知答 · 内部客服专用<span>依据平台知识生成 · 资料不足转人工</span></footer></main></div>
<div v-if="previewImage" class="modal image-preview" role="dialog" aria-modal="true" aria-label="问题截图预览" @click.self="previewImage=null" @keydown.esc="previewImage=null"><div class="card"><button type="button" class="quiet" @click="previewImage=null">关闭图片</button><p>{{previewImage.name}}</p><img :src="previewImage.data" :alt="previewImage.name"></div></div>
</template>
